#version 450

layout(local_size_x = 256) in;

layout(set = 0, binding = 0) buffer Data {
    uint input_data[];
};

layout(set = 0, binding = 1) buffer PrefixSum {
    uint output_data[];
};

layout(set = 0, binding = 2) buffer BlockSums {
    uint block_sums[];
};

shared uint temp[512];

void main() {
    uint g_idx = gl_GlobalInvocationID.x;
    uint l_idx = gl_LocalInvocationID.x;
    uint wg_idx = gl_WorkGroupID.x;

    // Load data into shared memory
    if (g_idx < 5000) {
        temp[l_idx] = input_data[g_idx];
    } else {
        temp[l_idx] = 0;
    }
    barrier();

    // Parallel exclusive scan (Blelloch)
    for (uint stride = 1; stride <= 256; stride <<= 1) {
        uint index = (l_idx + 1) * stride * 2 - 1;
        if (index < 512) {
            temp[index] += temp[index - stride];
        }
        barrier();
    }

    if (l_idx == 0) {
        block_sums[wg_idx] = temp[511];
        temp[511] = 0;
    }
    barrier();

    for (uint stride = 256; stride > 0; stride >>= 1) {
        uint index = (l_idx + 1) * stride * 2 - 1;
        if (index < 512) {
            uint t = temp[index - stride];
            temp[index - stride] = temp[index];
            temp[index] += t;
        }
        barrier();
    }

    if (g_idx < 5000) {
        output_data[g_idx] = temp[l_idx];
    }
}

#version 450
layout(local_size_x = 256) in;
layout(set = 0, binding = 0) buffer Output { uint data[]; };
layout(set = 0, binding = 1) buffer Offsets { uint offsets[]; };

void main() {
    uint g_idx = gl_GlobalInvocationID.x;
    uint wg_idx = gl_WorkGroupID.x;
    if (g_idx < 5000) {
        data[g_idx] += offsets[wg_idx];
    }
}

extends SceneTree

func _init():
    var rd = RenderingServer.create_local_rendering_device()
    var input_file = FileAccess.open("res://data/input.txt", FileAccess.READ)
    var count = int(input_file.get_line())
    var data = PackedInt32Array()
    for i in range(count):
        data.append(int(input_file.get_line()))
    input_file.close()

    var input_buffer = rd.storage_buffer_create(data.size() * 4, data.to_byte_array())
    var output_buffer = rd.storage_buffer_create(data.size() * 4)
    var block_sums = rd.storage_buffer_create(ceil(data.size() / 256.0) * 4)

    # Pass 1: Scan
    var shader_file = load("res://shader.glsl").spirv
    var pipeline = rd.compute_pipeline_create(rd.shader_create_from_spirv(shader_file))
    var set = rd.uniform_set_create([
        make_uniform(0, input_buffer),
        make_uniform(1, output_buffer),
        make_uniform(2, block_sums)
    ], rd.shader_create_from_spirv(shader_file), 0)

    var compute_list = rd.compute_list_begin()
    rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
    rd.compute_list_bind_uniform_set(compute_list, set, 0)
    rd.compute_list_dispatch(compute_list, ceil(data.size() / 256.0), 1, 1)
    rd.compute_list_end()
    rd.submit()
    rd.sync()

    # Pass 2: Add block sums
    var b_sums_bytes = rd.buffer_get_data(block_sums)
    var b_sums = b_sums_bytes.to_int32_array()
    var running_sum = 0
    var offsets = PackedInt32Array()
    for s in b_sums:
        offsets.append(running_sum)
        running_sum += s

    var offset_buffer = rd.storage_buffer_create(offsets.size() * 4, offsets.to_byte_array())
    var add_shader_file = load("res://add_shader.glsl").spirv
    var add_pipeline = rd.compute_pipeline_create(rd.shader_create_from_spirv(add_shader_file))
    var add_set = rd.uniform_set_create([
        make_uniform(0, output_buffer),
        make_uniform(1, offset_buffer)
    ], rd.shader_create_from_spirv(add_shader_file), 0)

    compute_list = rd.compute_list_begin()
    rd.compute_list_bind_compute_pipeline(compute_list, add_pipeline)
    rd.compute_list_bind_uniform_set(compute_list, add_set, 0)
    rd.compute_list_dispatch(compute_list, ceil(data.size() / 256.0), 1, 1)
    rd.compute_list_end()
    rd.submit()
    rd.sync()

    # Read back
    var final_data = rd.buffer_get_data(output_buffer).to_int32_array()

    # Calculate total sum
    var total = 0
    for val in data:
        total += val

    # Write JSON
    var result = {
        "count": count,
        "total": total,
        "prefix_sum": Array(final_data)
    }
    var json_string = JSON.stringify(result)
    var output_file = FileAccess.open("res://output/result.json", FileAccess.WRITE)
    output_file.store_string(json_string)
    output_file.close()

    quit()

func make_uniform(binding, buffer):
    var uniform = RDUniform.new()
    uniform.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
    uniform.binding = binding
    uniform.add_id(buffer)
    return uniform

